//! B5-PROF engine-side scenarios on a 24 MP (6000 × 4000) 8-bit document.
//! NOT part of the product: copied into crates/tessera-ffi/tests/ only for the
//! profiling run (see tools/orchestrate/wp/B5-prof/REPORT.md), then removed.
//! `cargo test -p tessera-ffi --release --test b5prof_bench -- --ignored --nocapture --test-threads 1 <name>`
//! Every "frame" figure is to the listener's completed frame (`wait_idle`).
//! Peak memory is the process phys_footprint sampled every 5 ms during the operation.
#![cfg(target_os = "macos")]

use compositor::{DocOp, DocState, Document, Layer, raster::Depth};
use engine_api::tile::{Extent, Tile, TileCoord};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::time::{Duration, Instant};
use tessera_ffi::surface::testing::create_rgba8;
use tessera_ffi::*;

const W: u32 = 6000;
const H: u32 = 4000;

fn engine() -> (tempfile::TempDir, Arc<Engine>) {
    let dir = tempfile::tempdir().unwrap();
    let engine = Engine::open(dir.path().join("support").to_string_lossy().into_owned()).unwrap();
    (dir, engine)
}

#[derive(Default)]
struct Recorder {
    frames: Mutex<Vec<(Instant, DocFrameInfo)>>,
    cv: Condvar,
}
impl DocumentListener for Recorder {
    fn on_frame(&self, frame: DocFrameInfo) {
        self.frames.lock().unwrap().push((Instant::now(), frame));
        self.cv.notify_all();
    }
    fn on_layers_changed(&self, _: Vec<u64>) {}
    fn on_history_changed(&self, _: u64) {}
    fn on_render_failed(&self, message: String) {
        eprintln!("render failed: {message}");
    }
}

fn footprint_mib() -> f64 {
    unsafe extern "C" {
        fn proc_pid_rusage(pid: i32, flavor: i32, buffer: *mut u64) -> i32;
    }
    let mut buf = [0u64; 32];
    let r = unsafe { proc_pid_rusage(std::process::id() as i32, 2, buf.as_mut_ptr()) };
    if r != 0 {
        return f64::NAN;
    }
    buf[9] as f64 / (1 << 20) as f64
}

/// Background sampler of phys_footprint; `measure` returns (ms, peak MiB, start MiB).
struct Meter {
    peak: Arc<AtomicU64>,
    stop: Arc<AtomicBool>,
}
impl Meter {
    fn new() -> Self {
        let peak = Arc::new(AtomicU64::new(0));
        let stop = Arc::new(AtomicBool::new(false));
        let (p, s) = (peak.clone(), stop.clone());
        std::thread::spawn(move || {
            while !s.load(Ordering::Relaxed) {
                p.fetch_max((footprint_mib() * 16.0) as u64, Ordering::Relaxed);
                std::thread::sleep(Duration::from_millis(5));
            }
        });
        Meter { peak, stop }
    }
    fn measure<T>(&self, label: &str, f: impl FnOnce() -> T) -> (T, f64) {
        let load=std::process::Command::new("/usr/sbin/sysctl").args(["-n","vm.loadavg"]).output().unwrap();
        eprintln!("LOAD {label}: {}",String::from_utf8_lossy(&load.stdout).trim());
        let start = footprint_mib();
        self.peak.store((start * 16.0) as u64, Ordering::Relaxed);
        eprintln!("MARK begin {} {label}", std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs_f64());
        let t = Instant::now();
        let out = f();
        let ms = t.elapsed().as_secs_f64() * 1000.0;
        eprintln!("MARK end {} {label}", std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs_f64());
        std::thread::sleep(Duration::from_millis(10));
        let peak = self.peak.load(Ordering::Relaxed) as f64 / 16.0;
        eprintln!("RESULT {label}: {ms:.1} ms, footprint start {start:.0} MiB peak {peak:.0} MiB (+{:.0})", peak - start);
        (out, ms)
    }
}
impl Drop for Meter {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Relaxed);
    }
}

fn pct(v: &[f64], p: f64) -> f64 {
    let mut s = v.to_vec();
    s.sort_by(f64::total_cmp);
    s[((s.len() - 1) as f64 * p).round() as usize]
}
fn summary(label: &str, v: &[f64]) {
    eprintln!(
        "RESULT {label}: n {} p50 {:.2} ms p95 {:.2} ms max {:.2} ms",
        v.len(),
        pct(v, 0.5),
        pct(v, 0.95),
        pct(v, 1.0)
    );
}

/// Opaque 8-bit photo stand-in (same generator as document_perf.rs `photo_layer`).
fn photo_layer(name: &str, e: Extent) -> Layer {
    let mut l = Layer::pixel(name.to_owned(), e, Depth::U8);
    let r = l.raster_mut().unwrap();
    let (cols, rows) = r.grid();
    for ty in 0..rows {
        for tx in 0..cols {
            let layout = r.layout(tx, ty);
            let n = layout.plane_len();
            let mut v = vec![255u8; 4 * n];
            let mut x = 0x2545_f491u32 ^ (tx << 16) ^ ty;
            for py in 0..layout.extent.height as usize {
                for px in 0..layout.extent.width as usize {
                    x ^= x << 13;
                    x ^= x >> 17;
                    x ^= x << 5;
                    let (gx, gy) = (tx as usize * 256 + px, ty as usize * 256 + py);
                    let i = py * layout.stride() + px;
                    v[i] = ((gx / 3) % 256) as u8 ^ (x as u8 >> 3);
                    v[n + i] = ((gy / 2) % 256) as u8 ^ ((x >> 8) as u8 >> 3);
                    v[2 * n + i] = (((gx + gy) / 5) % 256) as u8;
                }
            }
            r.set_slot(
                tx,
                ty,
                Some(Tile::from_samples(TileCoord::new(0, tx, ty), layout, v).unwrap()),
                1,
            )
            .unwrap();
        }
    }
    l
}

/// Two-layer 24 MP document (photo + a second photo layer at 60 % multiply), fit surface attached.
fn doc24(engine: &Arc<Engine>, layers: usize) -> (Arc<DocumentSession>, Arc<Recorder>, Vec<u64>) {
    let e = Extent::new(W, H);
    let mut d = Document::new(DocState::new(e, Depth::U8));
    for i in 0..layers {
        d.apply(DocOp::AddLayer {
            parent: None,
            index: usize::MAX,
            layer: photo_layer(&format!("photo {i}"), e),
        })
        .unwrap();
    }
    let s = engine.adopt_document(d, "b5prof 24 MP".into());
    let rec = Arc::new(Recorder::default());
    s.set_listener(Some(rec.clone()));
    let ids: Vec<u64> = s.layers().unwrap().iter().map(|l| l.id).collect();
    if ids.len() > 1 {
        s.set_opacity(ids[0], 0.6, false).unwrap();
        s.set_blend_mode(ids[0], "multiply".into()).unwrap();
    }
    (s, rec, ids)
}

fn attach(s: &DocumentSession, w: u32, h: u32) {
    for _ in 0..3 {
        s.attach_surface(create_rgba8(w, h), w, h).unwrap();
    }
}

fn fit(s: &DocumentSession) {
    attach(s, 1536, 1024);
    s.set_viewport(2, 0, 0, 1500, 1000, 0.25).unwrap();
    s.wait_idle();
}


