#[ignore]
fn prof_paint_undo_repeated_24mp() {
    let (_d, engine) = engine();
    let (s, rec, ids) = doc24(&engine, 2);
    fit(&s);
    let layer = ids[1];
    let m = Meter::new();
    let brush = PaintBrush {
        size: 100.0,
        hardness: 1.0,
        opacity: 1.0,
        flow: 1.0,
        spacing: 0.1,
        angle: 0.0,
        roundness: 1.0,
        blend_mode: "normal".into(),
        pressure_size: false,
        pressure_opacity: false,
        pressure_flow: false,
        smoothing: 0.0,
        symmetry: PaintSymmetry::None,
        symmetry_x: 0.0,
        symmetry_y: 0.0,
        symmetry_count: 6,
        tip_id: None,
        sample_all_layers: false,
    };
    let red = PaintColor { r: 1.0, g: 0.0, b: 0.0 };
    let (mut calls, mut raster, mut frames, mut ends, mut undos, mut redos) =
        (vec![], vec![], vec![], vec![], vec![], vec![]);
    for k in 0..1 {
        let y = 800.0 + k as f32 * 500.0;
        s.begin_stroke(layer, StrokeTarget::Pixels, StrokeTool::Brush, brush.clone(), red)
            .unwrap();
        for i in 0..180 {
            let x0 = 1200.0 + i as f32 * 20.0;
            let pts: Vec<StrokeSample> = (0..=2)
                .map(|j| StrokeSample {
                    x: x0 + j as f32 * 10.0,
                    y: y + (i as f32 * 0.1).sin() * 80.0,
                    pressure: 1.0,
                    tilt_x: 0.0,
                    tilt_y: 0.0,
                    timestamp: 0.0,
                })
                .collect();
            let t = Instant::now();
            let f = s.stroke_points(pts).unwrap();
            calls.push(t.elapsed().as_secs_f64() * 1000.0);
            raster.push(f.raster_ms);
            s.wait_idle();
            frames.push(t.elapsed().as_secs_f64() * 1000.0);
        }
        let (_, ms) = m.measure(&format!("stroke {k} end_stroke"), || s.end_stroke().unwrap());
        ends.push(ms);
        s.wait_idle();
        let (_, ms) = m.measure(&format!("stroke {k} undo→frame"), || {
            s.undo().unwrap();
            s.wait_idle();
        });
        undos.push(ms);
        let (_, ms) = m.measure(&format!("stroke {k} redo→frame"), || {
            s.redo().unwrap();
            s.wait_idle();
        });
        redos.push(ms);
    }
    summary("paint 24MP stroke_points call (main-thread FFI)", &calls);
    summary("paint 24MP engine raster_ms", &raster);
    summary("paint 24MP stroke_points → completed fit frame", &frames);
    summary("paint 24MP end_stroke", &ends);
    summary("paint 24MP undo stroke → frame", &undos);
    summary("paint 24MP redo stroke → frame", &redos);
    eprintln!("frames delivered {}", rec.frames.lock().unwrap().len());
    eprintln!("history bytes {}", s.history_memory_bytes().unwrap());
    for i in 0..3 {
        m.measure(&format!("paint undo redo 500 cycles {i}"),||{
            for _ in 0..500 {s.undo().unwrap();s.wait_idle();s.redo().unwrap();s.wait_idle();}
        });
    }
    s.close();
}

