fn prof_viewport_vs_full_24mp() {
    let (_d, engine) = engine();
    let (s, rec, ids) = doc24(&engine, 2);
    attach(&s, 3840, 2160);
    let m = Meter::new();
    for viewport in [true, false] {
        s.set_viewport_rendering(viewport);
        let tag = if viewport { "viewport" } else { "full-level" };
        m.measure(&format!("{tag} first 100% 4K frame"), || {
            s.set_viewport(0, 700 + viewport as u32 * 3, 700, 3840, 2160, 1.0).unwrap();
            s.wait_idle();
        });
        std::thread::sleep(Duration::from_secs(3));
        let mut pan = vec![];
        for i in 0..30 {
            let t = Instant::now();
            s.set_viewport(0, 500 + (i % 8) * 97, 500 + (i % 5) * 61, 3840, 2160, 1.0).unwrap();
            s.wait_idle();
            pan.push(t.elapsed().as_secs_f64() * 1000.0);
        }
        summary(&format!("{tag} 24MP 100% 4K pan → frame"), &pan);
        let mut op = vec![];
        for i in 0..30 {
            let t = Instant::now();
            s.set_opacity(ids[0], 0.3 + (i % 10) as f32 * 0.05, true).unwrap();
            s.wait_idle();
            op.push(t.elapsed().as_secs_f64() * 1000.0);
        }
        s.commit("Opacity".into()).unwrap();
        summary(&format!("{tag} 24MP 100% 4K opacity → frame"), &op);
        let rs: Vec<f64> = rec.frames.lock().unwrap().iter().rev().take(40).map(|(_, f)| f.render_ms).collect();
        summary(&format!("{tag} 24MP engine render_ms (last 40)"), &rs);
        eprintln!("{tag} resources: {}", s.render_resources());
        let recs: Vec<DocRenderRecord> = s.render_records().into_iter().rev().take(60).filter(|r| !r.dropped).collect();
        if let Some(r) = recs.first() {
            eprintln!("{tag} last record: {r:?}");
        }
        for (name, f) in [
            ("lock_wait_ms", (|r: &DocRenderRecord| r.lock_wait_ms) as fn(&DocRenderRecord) -> f64),
            ("lock_held_ms", |r| r.lock_held_ms),
            ("prep_ms", |r| r.prep_ms),
            ("composite_ms", |r| r.composite_ms),
            ("gpu_ms", |r| r.gpu_ms),
            ("total_ms", |r| r.total_ms),
        ] {
